{
  "apiVersion": 1,
  "type": "template.show",
  "package": "@astryxdesign/core",
  "data": {
    "template": "CodeBlockTerminal",
    "description": "A dark terminal-style command block: a bash CodeBlock wrapped in SyntaxTheme with the GitHub Dark preset, copy button on, and no line numbers. Use for shell sessions or CLI output that should read as a terminal even on light pages. Reach for a dark syntax preset instead of hand-rolling a dark box with custom CSS.",
    "type": "block",
    "components": [
      "CodeBlock",
      "SyntaxTheme"
    ],
    "source": "// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {SyntaxTheme} from '@astryxdesign/core/theme';\nimport {githubDark} from '@astryxdesign/core/theme/syntax';\nimport {CodeBlock} from '@astryxdesign/core/CodeBlock';\n\nconst commands = `$ astryx init --features agents\n✓ AI agent docs installed → AGENTS.md\n$ pnpm astryx component CodeBlock --dense`;\n\nexport default function CodeBlockTerminal() {\n  return (\n    <SyntaxTheme theme={githubDark}>\n      <CodeBlock\n        code={commands}\n        language=\"bash\"\n        hasCopyButton\n        style={{width: '100%', maxWidth: 480}}\n      />\n    </SyntaxTheme>\n  );\n}\n",
    "demoMediaReplaced": 0,
    "demoContentReplaced": 0
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
